-- ===== setup =====
-- Phase 106 setup (runs BEFORE the migration): a customer, the admin, one cart item and an order payload.
create temp table rehearsal_ids(k text primary key, id uuid, v numeric);
create temp table rehearsal_payload(p jsonb);
do $setup$
declare customer_id uuid; admin_id uuid; v public.product_variants; method text;
begin
  select ur.user_id into customer_id from public.user_roles ur where ur.role = 'customer' order by ur.created_at limit 1;
  select ur.user_id into admin_id from public.user_roles ur where ur.role = 'admin' order by ur.created_at limit 1;
  select pv.* into v from public.product_variants pv join public.products pr on pr.id = pv.product_id left join public.categories c on c.id = pr.category_id
   where pv.is_active and pv.min_qty <= 1 and pr.status = 'active' and pr.kind = 'standard' and not coalesce(pr.is_test_product, false)
     and (pr.category_id is null or c.is_active) order by pv.price desc limit 1;
  select code into method from public.payment_methods where active and code <> 'paymongo' order by code limit 1;
  insert into rehearsal_payload values (jsonb_build_object('name', 'Rehearsal', 'phone', '09171234567', 'notes', 'phase 106 rehearsal', 'payment_method', method,
    'fulfillment', 'pickup', 'items', jsonb_build_array(jsonb_build_object('variant_id', v.id, 'qty', 1))));
  insert into rehearsal_ids values ('customer', customer_id, null), ('admin', admin_id, null);
end $setup$;
-- an open slot N days ahead (Manila), or null
create or replace function pg_temp.slot_in(days integer) returns uuid language sql as $$
  select s.id from public.availability_slots s
   where s.is_open and (s.starts_at at time zone 'Asia/Manila')::date = (now() at time zone 'Asia/Manila')::date + days
     and (select count(*) from public.orders o where o.slot_id = s.id and o.status <> 'cancelled') < s.capacity
   order by s.starts_at limit 1
$$;

-- ===== phase 106 =====
-- Phase 106 · Two days' notice and the new rush fee.
-- What this does, in plain words (all dates are Philippine time):
--   1. Customers can no longer order for today or tomorrow. The earliest day is two days ahead
--      (on Nov 8 the first day they can pick is Nov 10). The owner (admin) is not limited, so you can still
--      add a reservation for any day yourself. Only a new order, or a changed pickup/delivery day, is checked.
--   2. The rush fee now depends on how many days ahead the order is for, counted from the day it is placed:
--        2 days ahead            → ₱400
--        3 or 4 days ahead       → ₱200
--        5 days ahead or more    → no rush fee
--      (e.g. placed Nov 8: Nov 10 = ₱400, Nov 11–12 = ₱200, Nov 13 onwards = ₱0)
--      Like before, the fee is added once when the order is placed and kept on the order; orders already placed
--      keep the fee they had.
-- Safe to run more than once.

-- the fee for a pickup/delivery day, counted from today
create or replace function private.rush_fee_for(receiving_day date) returns numeric
language sql stable set search_path = '' as $$
  select case when receiving_day is null then 0
              when receiving_day - (now() at time zone 'Asia/Manila')::date <= 2 then 400
              when receiving_day - (now() at time zone 'Asia/Manila')::date <= 4 then 200
              else 0 end::numeric
$$;
revoke all on function private.rush_fee_for(date) from public;
grant execute on function private.rush_fee_for(date) to authenticated;

-- same trigger as phase 59, now with the fee from the table above
create or replace function private.order_rush_fee() returns trigger
language plpgsql set search_path = '' as $$
declare fee numeric := 0;
begin
  if new.receiving_start is not null then
    fee := private.rush_fee_for((new.receiving_start at time zone 'Asia/Manila')::date);
  end if;
  if fee > 0 then
    new.rush_fee := fee;
    if new.total_amount is not null then
      new.total_amount := new.total_amount + fee;
      new.deposit_due := round(new.total_amount * new.deposit_rate, 2);
    end if;
  end if;
  return new;
end $$;
revoke all on function private.order_rush_fee() from public;

-- the booking-window trigger (phase 57) also checks the two days' notice for customers
create or replace function private.enforce_booking_horizon() returns trigger
language plpgsql set search_path = '' as $$
declare earliest date := (now() at time zone 'Asia/Manila')::date + 2;
begin
  if new.receiving_start is not null and (new.receiving_start at time zone 'Asia/Manila')::date > private.booking_horizon() then
    raise exception 'Bookings are open until %. Please choose an earlier date.', to_char(private.booking_horizon(), 'FMMonth FMDD, YYYY') using errcode = '22023';
  end if;
  if new.receiving_start is not null and not coalesce(private.is_admin(), false)
     and (tg_op = 'INSERT' or new.receiving_start is distinct from old.receiving_start)
     and (new.receiving_start at time zone 'Asia/Manila')::date < earliest then
    raise exception 'Orders need at least 2 days'' notice. The earliest day you can choose is %.', to_char(earliest, 'FMMonth FMDD, YYYY') using errcode = '22023';
  end if;
  return new;
end $$;
revoke all on function private.enforce_booking_horizon() from public;


-- ===== checks =====
-- Phase 106 checks: the fee table, two days' notice for customers, and the fee on a real order.
do $rehearsal$
declare report text := ''; ok boolean; pay jsonb := (select p from rehearsal_payload); res jsonb; o public.orders; d integer; s uuid;
  customer_id uuid := (select id from rehearsal_ids where k = 'customer'); slots uuid[] := array[pg_temp.slot_in(0), pg_temp.slot_in(1), pg_temp.slot_in(2), pg_temp.slot_in(3), null, null, pg_temp.slot_in(6)]; admin_id uuid := (select id from rehearsal_ids where k = 'admin');
begin
  foreach d in array array[2, 3, 4, 5, 9] loop
    report := report || E'\n' || case when private.rush_fee_for((now() at time zone 'Asia/Manila')::date + d) = case when d <= 2 then 400 when d <= 4 then 200 else 0 end then 'PASS' else 'FAIL' end
      || format('  %s days ahead → rush fee ₱%s', d, private.rush_fee_for((now() at time zone 'Asia/Manila')::date + d));
  end loop;

  perform set_config('request.jwt.claim.sub', customer_id::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', customer_id, 'role', 'authenticated')::text, true);
  perform set_config('role', 'authenticated', true);
  foreach d in array array[0, 1] loop
    s := slots[d + 1];
    if s is null then report := report || format(E'\nSKIP  no open slot %s day(s) ahead to try', d); continue; end if;
    begin
      res := public.create_order(pay || jsonb_build_object('request_id', gen_random_uuid(), 'slot_id', s));
      report := report || format(E'\nFAIL  a customer ordered %s day(s) ahead', d);
    exception when others then report := report || format(E'\nPASS  %s day(s) ahead refused: %s', d, sqlerrm); end;
  end loop;

  foreach d in array array[2, 3, 6] loop
    s := slots[d + 1];
    if s is null then report := report || format(E'\nSKIP  no open slot %s days ahead to try', d); continue; end if;
    res := public.create_order(pay || jsonb_build_object('request_id', gen_random_uuid(), 'slot_id', s));
    perform set_config('role', 'postgres', true);
    select * into o from public.orders where id = (res->>'id')::uuid;
    ok := o.rush_fee = case when d <= 2 then 400 when d <= 4 then 200 else 0 end
      and o.total_amount = o.items_subtotal + o.customization_total + coalesce(o.delivery_fee, 0) + o.rush_fee + o.vat_amount - coalesce(o.discount_amount, 0);
    report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || format('  order %s days ahead: rush ₱%s, items ₱%s, total ₱%s, downpayment ₱%s', d, o.rush_fee, o.items_subtotal, o.total_amount, o.deposit_due);
    perform set_config('role', 'authenticated', true);
  end loop;

  perform set_config('role', 'postgres', true);
  raise exception 'REHEARSAL REPORT (nothing was saved — this error undoes everything):%', report;
end $rehearsal$;
